# Existing B1 data files are split; locate each episode and rewrite in place.
files={}
for path in (ROOT/'data').glob('es-b1_*.json'):
 data=json.loads(path.read_text(encoding='utf-8'))
 for e in data: files[e['n']]=(path,e)
prev=files[418][1]
for p in P:
 path,e=files[p['n']]
 new=base.make(e,p,prev)
 new['t']=p['t']; new['s']=f"América Latina · {p['focus']} · referencia: {p['work']} · {p['year']}"
 new['lv']='B1'; new['cefr']='B1'; new['badge']='B1'
 for fr in new['fr']:
  if fr.get('k')=='cover':
   fr['badge']='B1'; fr['art']['seed']=f'es-b1-{p["n"]}'
 new['a']['w']=p['work']; new['a']['y']=p['year']; new['a']['d']=p['desc']
 new['h']['src']=p['work']
 new['presentation']='regular-pilot-v1'; new['pilot']=1
 files[p['n']]=(path,new); prev=new
for path in sorted(set(path for path,e in files.values())):
 data=json.loads(path.read_text(encoding='utf-8'))
 repl={n:e for n,(p,e) in files.items() if p==path and 419<=n<=428}
 if repl:
  for i,e in enumerate(data):
   if e['n'] in repl: data[i]=repl[e['n']]
  path.write_text(json.dumps(data,ensure_ascii=False,separators=(',',':')),encoding='utf-8')
print('wrote', [p['n'] for p in P])
